import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import CryptoJS from 'crypto-js';

const useMarvelApi = (query) => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [offset, setOffset] = useState(0);
  const [hasMore, setHasMore] = useState(true);

  const fetchNextPage = useCallback(() => {
    if (!query || loading) return;
    setLoading(true);

    const ts = new Date().getTime();
    const hash = CryptoJS.MD5(ts + process.env.REACT_APP_MARVEL_PRIVATE_KEY + process.env.REACT_APP_MARVEL_PUBLIC_KEY).toString();

    axios.get(`https://gateway.marvel.com:443/v1/public/characters`, {
      params: {
        apikey: process.env.REACT_APP_MARVEL_PUBLIC_KEY,
        ts,
        hash,
        nameStartsWith: query,
        offset,
        limit: 20,
      },
    }).then(response => {
      setData(prevData => [...prevData, ...response.data.data.results]);
      setOffset(prevOffset => prevOffset + response.data.data.count);
      setHasMore(response.data.data.total > offset + response.data.data.count);
    }).catch(setError).finally(() => setLoading(false));
  }, [query, loading, offset]);

  useEffect(() => {
    setOffset(0);
    setData([]);
    setHasMore(true);
    fetchNextPage();
  }, [query, fetchNextPage]);

  return { data, loading, error, hasMore, fetchNextPage };
};

export default useMarvelApi;
